STORES = ["vector", "lexical", "excerpt", "graph", "cache", "trace"]

@workflow.defn
class EraseWorkflow:
    @workflow.run
    async def run(self, tenant, uri, reason):
        eid = await workflow.execute_activity(open_row, args=[tenant, uri, reason], start_to_close_timeout=SHORT)
        lineage = await workflow.execute_activity(read_lineage, args=[tenant, uri], start_to_close_timeout=SHORT)
        results = await asyncio.gather(*[
            workflow.execute_activity(purge, args=[s, tenant, lineage.get(s, [])],
                                      start_to_close_timeout=LONG,
                                      retry_policy=RetryPolicy(maximum_attempts=0))   # retry until acknowledged
            for s in STORES])
        # Tricky part: an ack is not proof. Probe every store for the uri and its derived ids before closing.
        left = await workflow.execute_activity(probe_all, args=[tenant, uri, lineage], start_to_close_timeout=LONG)
        if left:
            await workflow.execute_activity(escalate, args=[eid, left], start_to_close_timeout=SHORT)
            raise ApplicationError("probe found residue", non_retryable=False)
        steps = [{"store": s, "state": "purged", "at": r} for s, r in zip(STORES, results)]
        return await workflow.execute_activity(close_with_receipt, args=[eid, steps], start_to_close_timeout=SHORT)

