ALLOWED = {("search", "index-service")}

def check_vector_op(opa, audit, tenant, op, caller):
    # Tricky part: ask the policy engine, but also hold a local default deny. If OPA is down, deny, never allow.
    try:
        ok = opa.query("brain/vector/allow", {"tenant": tenant, "op": op, "caller": caller})
    except Exception:
        ok = False
    if not ok or (op, caller) not in ALLOWED:
        audit.write({"event": "vector_denied", "tenant": tenant, "op": op, "caller": caller})
        raise Denied(op)

def rotation_due(policy, now):
    return (now - policy.last_rotated) / 86400 >= policy.rotate_days

async def rotate(tenant, db, kms, embed_model_new):
    new_dek = kms.create_dek(tenant, "vector")
    gen = db.next_generation(tenant)
    async for chunk in db.iter_chunks(tenant):                     # text re-read from the source, not stored
        vec = await embed_model_new(chunk.text_from_source())
        db.write_vector(tenant, chunk.id, vec, dek=new_dek, generation=gen)
    db.flip_generation(tenant, gen)                                # swap only after all chunks are written
    kms.retire_old_deks(tenant, "vector")

