import contextlib, re

_ID = re.compile(r"^[A-Za-z0-9_-]{1,64}$")

def tkey(tenant, obj):
    # Reject separators so tenant 'a:b' plus object 'c' cannot collide with tenant 'a' plus object 'b:c'.
    if not _ID.match(tenant) or ":" in obj:
        raise ValueError("bad tenant or object id")
    return f"{tenant}:{obj}"

@contextlib.contextmanager
def with_tenant(conn, tenant):
    if not _ID.match(tenant):
        raise ValueError("bad tenant id")
    with conn.transaction():
        # Tricky part: SET LOCAL ends with the transaction, so a pooled connection never keeps the last tenant.
        conn.execute("SELECT set_config('app.tenant', %s, true)", (tenant,))
        yield conn

def tenant_from_session(session):
    return session.claims["tenant"]       # from the verified token, never from the request body or query string

def route(shards, tenant):
    return shards[tenant].shard

