LEVEL = {"none": 0, "metadata": 1, "excerpt": 2}

def effective_policy(reg, app, tenant):
    row = reg.latest(app)
    if row is None:
        # No reviewed row means live only. Default deny, not default allow.
        return Policy(store="none", ttl_s=0, training=False, rate_per_min=1)
    ov = reg.tenant_override(tenant, app)
    ttl = min(row.max_ttl_s, ov.ttl_s) if ov and ov.ttl_s is not None else row.max_ttl_s
    store = row.store_allowed
    if ov and ov.store and LEVEL[ov.store] < LEVEL[store]:
        store = ov.store                                  # tenant can only be stricter
    share = ov.rate_share if ov and ov.rate_share else row.rate_ceiling_per_min
    return Policy(store=store, ttl_s=ttl, training=False,   # training is never allowed from this path
                  rate_per_min=min(row.rate_ceiling_per_min, share))

def check_write(reg, app, tenant, level, age_s):
    p = effective_policy(reg, app, tenant)
    if LEVEL[level] > LEVEL[p.store] or age_s > p.ttl_s:
        reg.audit("tos_blocked", app=app, tenant=tenant, level=level)
        raise TermsViolation(f"{app}: {level} write not allowed (policy {p.store}, ttl {p.ttl_s}s)")

