def kill(r, db, oauth, wf, audit, scope, id_, reason, actor):
    # Order matters: flag first so no new step starts, then drain, then revoke tokens.
    r.set(f"kill:{scope}:{id_}", "1")                       # sticky: no TTL
    db.insert_kill(scope, id_, "paused", reason, actor)
    wf.pause(scope, id_)
    deadline = time.time() + 60
    while time.time() < deadline and wf.in_flight(scope, id_):
        time.sleep(1)
    oauth.revoke_tokens(scope, id_)
    audit.write({"event": "kill", "scope": scope, "id": id_, "actor": actor, "reason": reason})

def is_killed(r, scope, id_):
    # Tricky part: fail closed. If the flag store is down, treat the scope as killed.
    try:
        return r.get(f"kill:{scope}:{id_}") is not None or r.get(f"kill:tenant:{tenant_of(scope, id_)}") is not None
    except Exception:
        return True

def request_purge(db, erase, audit, scope, id_, actor, approver):
    if scope == "tenant" and (approver is None or approver == actor):
        raise ApprovalRequired("tenant purge needs a second, different approver")
    db.set_state(scope, id_, "purging", approver=approver)
    erase.start(scope, id_)                                  # gv_erase does the deleting and the receipt
    audit.write({"event": "purge_requested", "scope": scope, "id": id_, "actor": actor, "approver": approver})

def lift(db, r, scope, id_, person):
    if not person:
        raise ValueError("a named person must lift a kill")
    r.delete(f"kill:{scope}:{id_}"); db.mark_lifted(scope, id_, person)

