def allowed(tenant, cls, terms):
    rule = lookup(tenant, cls) or StoreRule(may_store='pointer', excerpt_chars=0)
    capped = rule.cap_by(terms)            # vendor terms are the ceiling
    if capped.may_store == 'note' and not (rule.requires_sources and rule.requires_owner):
        raise ValueError('derived note needs a source list and an owner')
    return capped
